                if(stR.x >= 0.0 && stR.x <= 1.0 && stR.y >= 0.0 && stR.y <= 1.0)
                    avgValue += (amzTexture(texture, stR) * weightL);
            }
            return avgValue / coefficientSum;
        }
        void amzRender() {
            if( amzPass == 0 ) {
                amzOutput = amzTexture(0, amzScreenNorm().st);
            }
            else if( amzPass==1 ) {
                float2 texOffset = float2(1.0/screen.zw.x, 0.0);
                amzOutput = blurInternal(1, texOffset, float2(amzScreenNorm().s - amzp_sdx*(texOffset.x/1.0),amzScreenNorm().t), 0.5);
            } else {
                float2 texOffset = float2(0.0, 1.0/screen.zw.y);
                float4 result = blurInternal(2, texOffset, float2(amzScreenNorm().s, amzScreenNorm().t + amzp_sdy*(texOffset.y/1.0)), 0.5);
                float4 original = amzTexture(0,amzScreenNorm().st);
                result = original + amzp_color*result.a*amzp_alpha*(1.0-original.a);
                amzOutput = result;
            }
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
